const createInfiniteParams = <K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>>(queryKey: QueryKey<Options>, page: K) => {
    const params = { ...queryKey[0] };
    if (page.body) {
        params.body = {
            ...queryKey[0].body as any,
            ...page.body as any
        };
    }
    if (page.headers) {
        params.headers = {
            ...queryKey[0].headers,
            ...page.headers
        };
    }
    if (page.path) {
        params.path = {
            ...queryKey[0].path as any,
            ...page.path as any
        };
    }
    if (page.query) {
        params.query = {
            ...queryKey[0].query as any,
            ...page.query as any
        };
    }
    return params as unknown as typeof page;
};

export const listLegalResearchEntitiesInfiniteQueryKey = (options?: Options<ListLegalResearchEntitiesData>): QueryKey<Options<ListLegalResearchEntitiesData>> => createQueryKey('listLegalResearchEntities', options, true);

/**
 * Search people named in the corpus
 *
 * Advocates, judges and parties extracted from the corpus by wokil-rag — what makes "cases argued by advocate X" answerable. Paginated on offset/limit; `total` counts matches across the whole corpus.
 */
export const listLegalResearchEntitiesInfiniteOptions = (options?: Options<ListLegalResearchEntitiesData>) => {
    const opts = infiniteQueryOptions<ListLegalResearchEntitiesResponse, ListLegalResearchEntitiesError, InfiniteData<ListLegalResearchEntitiesResponse>, QueryKey<Options<ListLegalResearchEntitiesData>>, number | Pick<QueryKey<Options<ListLegalResearchEntitiesData>>[0], 'body' | 'headers' | 'path' | 'query'>>(
    // @ts-ignore
    {
        queryFn: async ({ pageParam, queryKey, signal }) => {
            // @ts-ignore
            const page: Pick<QueryKey<Options<ListLegalResearchEntitiesData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
                query: {
                    offset: pageParam
                }
            };
            const params = createInfiniteParams(queryKey, page);
            const { data } = await listLegalResearchEntities({
                ...options,
                ...params,
                signal,
                throwOnError: true
            });
            return data;
        },
        queryKey: listLegalResearchEntitiesInfiniteQueryKey(options)
    });
    return opts as Omit<typeof opts, 'initialData'>;
};

